from typing import Any

import jsonata  # type: ignore[import-untyped]

from voice_agent.utils.monitoring.logging import get_logger


logger = get_logger(__name__)


class CandidateDatapointValidator:
    def __init__(self, data: dict[str, Any]):
        self.data = data

    def validate(self, raw_expression: str) -> bool:
        """Validate a candidate datapoint using a JSONata expression."""
        try:
            expression = jsonata.Jsonata(raw_expression)
            result = expression.evaluate(self.data)
            return bool(result)
        except Exception as e:
            logger.exception(
                "Unable to evaluate JSONata expression",
                expression=raw_expression,
                data=self.data,
                error_type=type(e).__name__,
                error_message=str(e),
            )
            return False

